265	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
266	     */
267	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
268	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
269	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
270	        ownerFieldsDto.setTelephone(normalized);
